import { useMemo, useState } from 'react';
import {
  JxTextField,
  JxSelect,
  JxSwitch,
  JxButton,
  JxAlert,
} from '@jinx-ui/react';

const ROLE_OPTIONS = [
  { value: 'viewer', label: 'Наблюдатель' },
  { value: 'editor', label: 'Редактор' },
  { value: 'admin', label: 'Администратор' },
];

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [role, setRole] = useState('viewer');
  const [notify, setNotify] = useState(true);
  const [showSuccess, setShowSuccess] = useState(false);

  const emailTouched = email.length > 0;
  const emailValid = useMemo(() => EMAIL_PATTERN.test(email), [email]);
  const isInvalid = emailTouched && !emailValid;
  const canSubmit = emailValid;

  const handleSubmit = (event: React.FormEvent) => {
    event.preventDefault();
    if (!canSubmit) return;
    setShowSuccess(true);
  };

  return (
    <div className="jx-stack" style={{ gap: 'var(--jx-space-4)', maxWidth: 420 }}>
      {showSuccess && (
        <JxAlert
          variant="success"
          onDismiss={() => setShowSuccess(false)}
        >
          Приглашение для {email} отправлено.
        </JxAlert>
      )}

      <form className="jx-stack" style={{ gap: 'var(--jx-space-4)' }} onSubmit={handleSubmit}>
        <JxTextField
          label="Почта"
          type="email"
          value={email}
          onValueChange={setEmail}
          placeholder="name@company.com"
          helperText="Мы отправим приглашение на этот адрес."
          error={isInvalid}
          errorText={isInvalid ? 'Похоже, это не адрес почты' : undefined}
          required
        />

        <JxSelect
          label="Роль"
          value={role}
          onValueChange={setRole}
          options={ROLE_OPTIONS}
        />

        <JxSwitch
          checked={notify}
          onCheckedChange={setNotify}
          label="Отправить уведомление"
        />

        <JxButton type="submit" variant="primary" disabled={!canSubmit}>
          Отправить приглашение
        </JxButton>
      </form>
    </div>
  );
}

